/**
 * Authorization coverage registry for every API route (Final Wave gate).
 * Generated from the source tree and reviewed; route-coverage.test.ts fails on
 * any route that is missing here or classified UNKNOWN, and on any ENTERPRISE
 * route whose file (or declared helper) does not reference its permission.
 *
 *   PUBLIC      unauthenticated by design (auth flows, public content)
 *   CONSUMER    consumer / loyalty participant identity, never enterprise RBAC
 *   SERVICE     cron, webhook, agent or integration credential (sa_service_identities)
 *   SELF        the caller's own record only
 *   ENTERPRISE  decided by Security & Access (permissions below)
 *   EXCEPTION   documented compatibility exception
 *   EMPTY       file without handlers
 */
export type RouteCoverage =
  | { kind: 'PUBLIC' | 'CONSUMER' | 'SERVICE' | 'SELF' | 'EXCEPTION' | 'EMPTY'; reason: string }
  | { kind: 'ENTERPRISE'; permissions: string[]; via?: string[] }

